"""Optional Node.js/TypeScript companion (an explicit exception; off by default).

Default output is Rust only. With --node, a `node-client/` folder is added with a TypeScript
Connect client (fetch) for the generated actions. Choosing neither Node nor TypeScript is the default
and always produces a complete Rust-only result.
"""
from __future__ import annotations

import json
import os

from .reaxt_gen import _method_name

_HEAD = (
    "// Generated by 2rporea (optional --node). Connect unary calls: POST /<package>.<Service>/<Method> with JSON.\n"
    'const BASE = "";\n'
    "async function call(method: string, input: unknown) {\n"
    "  const r = await fetch(`${BASE}/app.v1.Routes/${method}`, "
    '{ method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(input) });\n'
    "  if (!r.ok) throw new Error(`${method}: ${r.status}`);\n"
    "  return r.json();\n"
    "}\n"
)

_TSCONFIG = '{"compilerOptions":{"target":"ES2022","module":"ES2022","strict":true,"lib":["ES2022","DOM"],"outDir":"dist"},"include":["src"]}\n'


def write(out: str, routes: list) -> str:
    d = os.path.join(out, "node-client")
    os.makedirs(os.path.join(d, "src"), exist_ok=True)
    with open(os.path.join(d, "package.json"), "w", encoding="utf-8", newline="\n") as fh:
        json.dump({"name": "ported-client", "version": "0.0.1", "private": True, "type": "module",
                   "devDependencies": {"typescript": "^5"}}, fh, indent=2)
        fh.write("\n")
    with open(os.path.join(d, "tsconfig.json"), "w", encoding="utf-8", newline="\n") as fh:
        fh.write(_TSCONFIG)
    seen, fns = set(), []
    for _fw, m, path, _f in routes:
        mn = _method_name(m, path)
        i, base = 2, mn
        while mn in seen:
            mn = f"{base}{i}"
            i += 1
        seen.add(mn)
        fns.append(f'export const {mn[:1].lower() + mn[1:]} = (input: unknown = {{}}) => call("{mn}", input); // from {m} {path}')
    p = os.path.join(d, "src", "client.ts")
    with open(p, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(_HEAD + "\n".join(fns) + "\n")
    return p
